WITH enriched AS (SELECT id, store_id, product_id, sale_date, units, revenue, NTILE(5) OVER (PARTITION BY product_id, store_id ORDER BY revenue DESC, id) AS revenue_bucket, ROUND(revenue / SUM(revenue) OVER (PARTITION BY product_id), 4) AS revenue_share, LEAD(revenue, 1) OVER (PARTITION BY product_id ORDER BY sale_date, id) AS next_revenue, ROW_NUMBER() OVER (PARTITION BY store_id ORDER BY revenue, id) AS event_seq, NTILE(5) OVER (PARTITION BY product_id ORDER BY units DESC, id) AS units_bucket FROM store_sales) SELECT product_id, DATE_TRUNC('YEAR', sale_date) AS year_start, CASE WHEN revenue >= 4400 THEN 'PREMIUM' ELSE 'STANDARD' END AS revenue_tier, APPROX_PERCENTILE(event_seq, ARRAY(0.25, 0.5, 0.75)) AS event_seq_quartiles, BIT_AND(units) AS units_bit_and, COUNT(DISTINCT product_id) AS distinct_product_ids FROM enriched GROUP BY product_id, DATE_TRUNC('YEAR', sale_date), CASE WHEN revenue >= 4400 THEN 'PREMIUM' ELSE 'STANDARD' END ORDER BY revenue_tier DESC;
